local PuppetMaker = {}
local PRODUCTS = {
    hand_puppet = { name = "Ročna lutka", clothCost = 1, woodCost = 1, time = 2, cost = 15, happiness = 3, description = "Preprosta ročna lutka." },
    marionette = { name = "Marioneta", woodCost = 3, clothCost = 2, threadCost = 1, time = 7, cost = 80, happiness = 6, prestige = 3, description = "Lutka na niti." },
    glove_puppet = { name = "Lutka rokavica", clothCost = 2, time = 3, cost = 25, happiness = 4, description = "Lutka iz rokavice." },
    shadow_puppet = { name = "Sencna lutka", leatherCost = 1, woodCost = 1, time = 4, cost = 40, happiness = 5, description = "Lutka za sence." },
    mechanical_puppet = { name = "Mehanska lutka", woodCost = 5, metalCost = 3, time = 14, cost = 200, happiness = 10, prestige = 8, description = "Avtomatska lutka." },
    royal_marionette = { name = "Kraljevska marioneta", woodCost = 5, clothCost = 3, goldCost = 1, jewelCost = 1, time = 20, cost = 500, happiness = 15, prestige = 20, description = "Luksuzna lutka za kralja." },
}
local BUILDINGS = {
    workshop = { name = "Lutkarska delavnica", cost = { gold = 200, wood = 100 }, upkeep = 5, qualityBonus = 5 },
    puppet_theater = { name = "Lutkovno gledališče", cost = { gold = 800, wood = 300, cloth = 50 }, upkeep = 20, qualityBonus = 15, happiness = 5 },
    marionette_studio = { name = "Marionetni atelje", cost = { gold = 1500, wood = 300, stone = 200 }, upkeep = 30, qualityBonus = 25, prestigeBonus = 5 },
    royal_puppeteer = { name = "Kraljevski lutkar", cost = { gold = 3000, wood = 400, stone = 500, gold = 50 }, upkeep = 60, qualityBonus = 35, prestigeBonus = 15 },
}
PuppetMaker.woodStock = 15; PuppetMaker.clothStock = 8; PuppetMaker.threadStock = 5; PuppetMaker.leatherStock = 5; PuppetMaker.metalStock = 5; PuppetMaker.goldStock = 3; PuppetMaker.jewelStock = 2
PuppetMaker.productStock = {}; PuppetMaker.buildings = {}; PuppetMaker.maker = nil; PuppetMaker.activeMaking = {}; PuppetMaker.totalProducts = 0; PuppetMaker.dayTimer = 0
function PuppetMaker.init() PuppetMaker.woodStock=15; PuppetMaker.clothStock=8; PuppetMaker.threadStock=5; PuppetMaker.leatherStock=5; PuppetMaker.metalStock=5; PuppetMaker.goldStock=3; PuppetMaker.jewelStock=2; PuppetMaker.productStock={}; PuppetMaker.buildings={}; PuppetMaker.maker=nil; PuppetMaker.activeMaking={}; PuppetMaker.totalProducts=0; PuppetMaker.dayTimer=0; print("[PuppetMaker] Royal Puppet & Marionette Maker System initialized (6 products, 4 buildings)") end
function PuppetMaker.hireMaker(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PuppetMaker.maker={name=n or ("Lutkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lutkar najet: %s (spretnost: %d)",PuppetMaker.maker.name,s),"success") end; return true end
function PuppetMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PuppetMaker.build(id) local ok,e=PuppetMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PuppetMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PuppetMaker.getQualityBonus() local b=0; for _,bd in ipairs(PuppetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PuppetMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and PuppetMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.clothCost and PuppetMaker.clothStock<(d.clothCost or 0) then return false,"Premalo blaga" end; if d.threadCost and PuppetMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.leatherCost and PuppetMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.metalCost and PuppetMaker.metalStock<(d.metalCost or 0) then return false,"Premalo kovine" end; if d.goldCost and PuppetMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PuppetMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo dragih kamnov" end; if #PuppetMaker.buildings==0 then return false,"Potrebna delavnica" end; if not PuppetMaker.maker then return false,"Potreben lutkar" end; return true end
function PuppetMaker.make(pt) local ok,e=PuppetMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then PuppetMaker.woodStock=PuppetMaker.woodStock-d.woodCost end; if d.clothCost then PuppetMaker.clothStock=PuppetMaker.clothStock-d.clothCost end; if d.threadCost then PuppetMaker.threadStock=PuppetMaker.threadStock-d.threadCost end; if d.leatherCost then PuppetMaker.leatherStock=PuppetMaker.leatherStock-d.leatherCost end; if d.metalCost then PuppetMaker.metalStock=PuppetMaker.metalStock-d.metalCost end; if d.goldCost then PuppetMaker.goldStock=PuppetMaker.goldStock-d.goldCost end; if d.jewelCost then PuppetMaker.jewelStock=PuppetMaker.jewelStock-d.jewelCost end; local t=d.time; if PuppetMaker.maker then t=math.max(1,t-math.floor(PuppetMaker.maker.skill/12)) end; table.insert(PuppetMaker.activeMaking,{id="puppet_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,happiness=d.happiness or 0,prestige=d.prestige or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %s (%d dni)",d.name,t),"info") end; return true end
function PuppetMaker.completeMaking(m) local q=1.0+(PuppetMaker.getQualityBonus()/100); if PuppetMaker.maker then q=q+(PuppetMaker.maker.skill/200) end; q=math.min(2.0,q); PuppetMaker.productStock[m.productType]=(PuppetMaker.productStock[m.productType] or 0)+1; PuppetMaker.totalProducts=PuppetMaker.totalProducts+1; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness*q) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if PuppetMaker.maker then PuppetMaker.maker.itemsMade=PuppetMaker.maker.itemsMade+1; if math.random()<0.15 then PuppetMaker.maker.skill=math.min(100,PuppetMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lutka izdelana: %s (kakovost: %.1f)",m.productName,q),"success") end end
function PuppetMaker.update(dt) if not _G.state then return end; PuppetMaker.dayTimer=PuppetMaker.dayTimer+dt; if PuppetMaker.dayTimer>=30 then PuppetMaker.dayTimer=0; for i=#PuppetMaker.activeMaking,1,-1 do local m=PuppetMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PuppetMaker.completeMaking(m); table.remove(PuppetMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PuppetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PuppetMaker.maker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PuppetMaker.getStats() return {woodStock=PuppetMaker.woodStock,clothStock=PuppetMaker.clothStock,productStock=PuppetMaker.productStock,numBuildings=#PuppetMaker.buildings,hasMaker=PuppetMaker.maker~=nil,makerName=PuppetMaker.maker and PuppetMaker.maker.name or "—",makerSkill=PuppetMaker.maker and PuppetMaker.maker.skill or 0,activeMaking=#PuppetMaker.activeMaking,totalProducts=PuppetMaker.totalProducts} end
return PuppetMaker
